 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]

    # Each colored cross projects along rows and columns. Its adjacent 3 arms
    # are passed through; any further 3 marker stops that ray. Existing marks
    # remain intact, and vertical projections are applied after horizontal.
    for r, c, color in centers:
        for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            y, x = r + dr, c + dc
            while 0 <= y < h and 0 <= x < w:
                if grid[y][x] == 3:
                    if abs(y-r) + abs(x-c) == 1:
                        y += dr
                        x += dc
                        continue
                    break
                if grid[y][x] == 0:
                    out[y][x] = color
                y += dr
                x += dc
    for r, c, color in centers:
        out[r][c] = color
    return out
